"""laoban web server (fixed template, not generated by AI).

Serves the three static files mounted from the ConfigMap and forwards
every request under api/ to the API service, stripping the api/ prefix.
The page is opened through the Rancher service proxy, which removes the
proxy prefix before the request reaches this server, so the page itself
must use relative URLs only. Python standard library only.

Environment:
  LAOBAN_STATIC_DIR  directory holding the static files (default /app)
  LAOBAN_API_URL     base URL of the API service, e.g. http://demo-api:8080/
  PORT               listen port (default 8080; 0 picks a free port)
"""

import http.server
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

STATIC_DIR = os.environ.get("LAOBAN_STATIC_DIR", "/app")
API_URL = os.environ.get("LAOBAN_API_URL", "")
PORT = int(os.environ.get("PORT", "8080"))
MAX_BODY = 1024 * 1024
TIMEOUT_SECONDS = 30

# Only these files are served; server.py itself is not.
FILES = {
    "index.html": "text/html; charset=utf-8",
    "app.js": "text/javascript; charset=utf-8",
    "style.css": "text/css; charset=utf-8",
}

# Never use a proxy from the environment for the in-cluster API call.
OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))


class Handler(http.server.BaseHTTPRequestHandler):
    server_version = "laoban-web"
    sys_version = ""
    protocol_version = "HTTP/1.0"

    def _send(self, status, body, content_type):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _text(self, status, message):
        self._send(status, (message + "\n").encode("utf-8"), "text/plain; charset=utf-8")

    def _route(self):
        path = urllib.parse.urlsplit(self.path).path
        if path == "/api" or path.startswith("/api/"):
            self._proxy(path)
            return
        if self.command not in ("GET", "HEAD"):
            self._text(405, "method not allowed")
            return
        name = path.lstrip("/") or "index.html"
        content_type = FILES.get(name)
        if content_type is None:
            self._text(404, "not found")
            return
        try:
            with open(os.path.join(STATIC_DIR, name), "rb") as f:
                body = f.read()
        except OSError:
            self._text(404, "not found")
            return
        self._send(200, body, content_type)

    def _proxy(self, path):
        if not API_URL:
            self._text(502, "api not configured")
            return
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            self._text(400, "bad content-length")
            return
        if length < 0 or length > MAX_BODY:
            self._text(413, "request body too large")
            return
        body = self.rfile.read(length) if length else None

        rest = path[len("/api"):].lstrip("/")
        target = API_URL.rstrip("/") + "/" + rest
        query = urllib.parse.urlsplit(self.path).query
        if query:
            target += "?" + query
        headers = {}
        for name in ("Content-Type", "Accept"):
            value = self.headers.get(name)
            if value:
                headers[name] = value
        request = urllib.request.Request(target, data=body, method=self.command, headers=headers)
        try:
            with OPENER.open(request, timeout=TIMEOUT_SECONDS) as resp:
                status = resp.status
                content_type = resp.headers.get("Content-Type", "application/json")
                data = resp.read(MAX_BODY)
        except urllib.error.HTTPError as err:
            status = err.code
            content_type = err.headers.get("Content-Type", "application/json")
            data = err.read(MAX_BODY)
        except (urllib.error.URLError, OSError):
            self._send(502, b'{"error":"api unavailable"}', "application/json")
            return
        self._send(status, data, content_type)

    do_GET = _route
    do_HEAD = _route
    do_POST = _route
    do_PUT = _route
    do_PATCH = _route
    do_DELETE = _route


def main():
    server = http.server.ThreadingHTTPServer(("", PORT), Handler)
    server.daemon_threads = True
    print("laoban-web listening on port %d" % server.server_address[1], file=sys.stderr, flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()
